/** A network segment of the associated vRack. It represents an IP addressing scheme inside the private network. */
export interface VrackServicesSubnet {
  /**
   * Availability zone
   *
   * Read-only: the API sets it.
   */
  az?: string | undefined;
  /**
   * IP address range of the subnet in CIDR format
   *
   * Read-only: the API sets it.
   */
  cidr?: IPBlock | undefined;
  /**
   * Display name of the subnet
   *
   * Read-only: the API sets it.
   */
  displayName?: string | null | undefined;
  /**
   * Unique inner VLAN that allows subnets segregation
   *
   * Read-only: the API sets it.
   */
  vlan?: number | null | undefined;
}

/** Target specification of a subnet */
export interface VrackServicesTargetSubnet {
  /** Availability zone of the subnet, one of the vRack Services region zones (`<region>-a` today). Immutable once the subnet exists: a change is ignored, delete and recreate the subnet instead. */
  az: string;
  /** IP address range of the subnet in CIDR format. Must be a private network address (RFC 1918 for IPv4, RFC 4193 for IPv6). Authorized prefix length: /23 to /24 for IPv4, /64 for IPv6. */
  cidr: IPBlock;
  /** Display name of the subnet. Format must follow `^[ a-zA-Z0-9-_.]{0,40}$`. */
  displayName?: string | null | undefined;
  /** Unique inner VLAN that allows subnets segregation. Authorized values: [2 - 4094] and `null` (untagged traffic). Must be `null` for an IPv6 subnet, and when the subnet is referenced by a BGP range (see `bgp.bgpRange[].subnetCidr`). Only one untagged subnet is allowed per IP version and per availability zone. */
  vlan?: number | null | undefined;
}

